package com.shopsphere;import static org.assertj.core.api.Assertions.assertThat;import com.mongodb.client.MongoClients;import org.bson.Document;import org.junit.jupiter.api.Test;import org.testcontainers.containers.MongoDBContainer;import org.testcontainers.junit.jupiter.*;
@Testcontainers(disabledWithoutDocker=true)class ProductPersistenceContainerTest{@Container static MongoDBContainer mongo=new MongoDBContainer("mongo:8.0");@Test void documentsRoundTrip(){try(var client=MongoClients.create(mongo.getReplicaSetUrl())){var collection=client.getDatabase("catalog").getCollection("products");collection.insertOne(new Document("sku","SKU-1"));assertThat(collection.countDocuments()).isEqualTo(1);}}}
